export const TEAM_FOLDERS_DIR = join(DATA_DIR, "vm-teams");
export function teamFolderDir(team: string): string {
  return join(TEAM_FOLDERS_DIR, createHash("sha256").update(`limix-team-folder:${team}`).digest("hex").slice(0, 16));
}

